import{_ as a,c as o,o as e,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"CSDN 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-csdn.md","filePath":"platforms/custom-csdn.md","lastUpdated":1790228279000}'),i={name:"platforms/custom-csdn.md"};function l(d,t,s,n,c,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="csdn-配置指南" tabindex="-1">CSDN 配置指南 <a class="header-anchor" href="#csdn-配置指南" aria-label="Permalink to &quot;CSDN 配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到 CSDN。图片默认上传到 CSDN。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>在浏览器登录 CSDN 创作中心。</li><li>无需 API Token，只用 Cookie。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://blog.csdn.net</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认 <code>https://bizapi.csdn.net</code>，一般不改</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/[userid]/article/details/[postid]</code></td></tr><tr><td>发布格式</td><td><strong>必须选 HTML</strong>，CSDN 目前只接受 HTML 模式</td></tr><tr><td>标签</td><td><strong>必填</strong>，这是 CSDN 平台规定，标签不能为空</td></tr><tr><td>图床</td><td>默认「当前平台」，图片随文章上传到 CSDN</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">发布格式与标签</p><ul><li>发布格式选 <strong>HTML</strong>，选 Markdown 会出现发布异常（知乎同理）。</li><li>标签<strong>不能为空</strong>，需在发布前填好。</li></ul></div><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 登录 CSDN 创作中心 → <strong>关闭登录窗口</strong> → 点「2 自动读取 Cookie」。</li><li>点「验证」→ 通过后保存。</li><li>快速发布 → 选 CSDN → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="过一段时间提示无法授权、需要登录" tabindex="-1">过一段时间提示无法授权、需要登录 <a class="header-anchor" href="#过一段时间提示无法授权、需要登录" aria-label="Permalink to &quot;过一段时间提示无法授权、需要登录&quot;">​</a></h3><p>这是 Cookie 过期。有一个办法可以解决：</p><ol><li>安装「网页视图」插件，在思源内打开 CSDN 首页并<strong>退出登录</strong>；</li><li>回到插件配置页，重新授权。</li></ol><div class="tip custom-block"><p class="custom-block-title">必须在思源的网页视图里退出</p><p>在外部浏览器退出登录不会同步，所以这一步要放在思源的网页视图里做。</p></div><h3 id="发布时报标签为空" tabindex="-1">发布时报标签为空 <a class="header-anchor" href="#发布时报标签为空" aria-label="Permalink to &quot;发布时报标签为空&quot;">​</a></h3><p>CSDN 强制要求标签，发布前请先填好标签再提交。</p><h3 id="cookie-验证失败" tabindex="-1">Cookie 验证失败 <a class="header-anchor" href="#cookie-验证失败" aria-label="Permalink to &quot;Cookie 验证失败&quot;">​</a></h3><p>确认浏览器已登录 CSDN 创作中心，重新读取 Cookie。</p><h3 id="图片图床" tabindex="-1">图片图床 <a class="header-anchor" href="#图片图床" aria-label="Permalink to &quot;图片图床&quot;">​</a></h3><p>默认「当前平台」即可，无需额外配置 PicGo。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>其他 Cookie 授权平台：<a href="/siyuan-plugin-publisher/platforms/">平台支持</a></li><li>通用排查：<a href="/siyuan-plugin-publisher/guide/faq.html">常见问题</a></li></ul>',22)])])}const b=a(i,[["render",l]]);export{p as __pageData,b as default};
